import{_ as a,a as t,c as n,ac as i}from"./chunks/framework.BSuaGltH.js";const f=JSON.parse('{"title":"数学：函数、计数与证明","description":"用平方函数、无放回选人与数学归纳法练习定义域、计数顺序和证明条件。","frontmatter":{"title":"数学：函数、计数与证明","description":"用平方函数、无放回选人与数学归纳法练习定义域、计数顺序和证明条件。","showdocs":{"topics":[{"id":"math","title":"数学","link":"/topics/math/"}],"kind":"公式与参考","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"数学：前置关系与代数起点","summary":"用平方函数、无放回选人与数学归纳法练习定义域、计数顺序和证明条件。","status":"active","related":[{"title":"八年级数学独立习题集","link":"/life/math/junior/grade-8/exercises","kind":"习题与解析","scope":"general","audience":"general"},{"title":"八年级数学独立习题集 · 平方根、立方根与实数至一次函数与实际方案比较","link":"/life/math/junior/grade-8/exercises-part-01","kind":"习题与解析","scope":"general","audience":"general"},{"title":"八年级数学独立习题集 · 三角形全等与对应关系至加权平均数与方差","link":"/life/math/junior/grade-8/exercises-part-02","kind":"习题与解析","scope":"general","audience":"general"},{"title":"八年级数学知识讲解","link":"/life/math/junior/grade-8/knowledge","kind":"知识讲解","scope":"general","audience":"general"},{"title":"八年级数学知识讲解 · 等腰三角形与垂直平分线至加权平均数与方差","link":"/life/math/junior/grade-8/knowledge-part-02","kind":"知识讲解","scope":"general","audience":"general"}],"prev":{"text":"数学：前置关系与代数起点","link":"/life/math/foundations/prerequisites"},"next":{"text":"数学：概率与方程完整习题","link":"/life/math/exercises/workbook"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"数学：前置关系与代数起点","link":"/life/math/foundations/prerequisites"},"next":{"text":"数学：概率与方程完整习题","link":"/life/math/exercises/workbook"}},"headers":[],"relativePath":"life/math/foundations/structures.md","filePath":"life/math/foundations/structures.md"}'),r={name:"life/math/foundations/structures.md"};function o(s,e,l,c,d,u){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="数学-函数、计数与证明" tabindex="-1">数学：函数、计数与证明 <a class="header-anchor" href="#数学-函数、计数与证明" aria-label="Permalink to &quot;数学：函数、计数与证明&quot;">​</a></h1><p>需先会实数四则、阶乘与简单等式变形。本页用平方函数的反函数条件、选人与分配职务、正整数归纳证明三个例子练习“条件改变，结论怎样改变”；<a href="/life/math/exercises/workbook">条件概率与方程习题</a>可继续练习。例题为原创教学材料。</p><h2 id="functions" tabindex="-1">函数与变化 <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;函数与变化 {#functions}&quot;">​</a></h2><p>数学 函数与变化先给定义域。f(x)=x²在实数域上不是一一对应，因为f(1)=f(-1)=1；限制x≥0后才可用非负平方根作反函数。平均变化率是[f(b)-f(a)]/(b-a)，要求b不等于a。</p><p>题：f(x)=x²从1到3的平均变化率。答案(9-1)/(3-1)=4，不是末端函数值9。若考察x到x+h，差商为((x+h)²-x²)/h=2x+h，h≠0；只有进一步讨论h趋近0才得到导数2x，不能直接把0放进原分式。</p><h2 id="counting" tabindex="-1">排列组合 <a class="header-anchor" href="#counting" aria-label="Permalink to &quot;排列组合 {#counting}&quot;">​</a></h2><p>数学 排列组合先问交换顺序是否产生新结果。从A、B、C中选两人：无职务是AB、AC、BC共3组；分配主持和记录两个不同职务则AB与BA不同，共3乘2=6种。</p><p>一般从n个不同对象无放回取k个有序位置，得到n!/(n-k)!；每个无序集合对应k!种顺序，故组合数为n!/[k!(n-k)!]，要求0≤k≤n为整数。题：4人选2人，无序6组、有序12种。若允许同一个人重复占位，模型改变，不能继续套无放回公式。</p><h2 id="proof" tabindex="-1">归纳证明 <a class="header-anchor" href="#proof" aria-label="Permalink to &quot;归纳证明 {#proof}&quot;">​</a></h2><p>数学 归纳证明包括基例、归纳假设和递推一步。证明1+...+n=n(n+1)/2，n为正整数。基例n=1，两边都等于1。假设n=k成立；到k+1时加上k+1，和为k(k+1)/2+(k+1)=(k+1)(k+2)/2，正是所需形式。</p><p>只检查n=1、2、3是有限验证，不是对所有正整数的证明。练习证明前n个奇数和为n²：基例1=1；假设和为k²，下一个奇数为2k+1，相加得(k+1)²。归纳步必须从假设推出下一项，不能直接重复待证结论。</p>',11)])])}const h=a(r,[["render",o]]);export{f as __pageData,h as default};
